void sourceContactChoiceLabels(){
  Form form;form.setSize(920,680);const auto fence=[] {return true;};
  const V symbolic=O{{"string","G"},{"fret",integer(7)}};
  const V numeric=O{{"string",integer(3)},{"fret",integer(7)}};
  const V field=O{{"type","object"},{"enum",A{symbolic,numeric}},{"input_role","explicit_chosen_contact"}};
  form.configure(object({{"contact",field}}),{},fence);
  auto& menu=control<juce::ComboBox>(form,"typed-field-input/contact");
  check(menu.getSelectedId()==0,"Contact string enum must remain blank");
  check(menu.getItemText(0)=="String G, fret 7"&&menu.getItemText(1)=="String 3, fret 7","Source contacts need readable string/fret labels");
  menu.setSelectedId(1,juce::dontSendNotification);check(f(form.read(),"contact")==symbolic,"Symbolic source string changed type/value");
  menu.setSelectedId(2,juce::dontSendNotification);check(f(form.read(),"contact")==numeric,"Numeric source string changed type/value");
  auto bound=field;bound.object().emplace("const",numeric);bound.object().emplace("literal_binding_label","source_protocol_binding");
  form.configure(object({{"contact",bound}}),{},fence);
  check(control<juce::Label>(form,"typed-label-input/contact").getText().contains("String 3, fret 7"),"Numeric literal source binding unreadable");
  check(f(form.read(),"contact")==numeric&&!find(form,"typed-field-input/contact"),"Literal source contact became editable");
  auto malformed=field;malformed.object()["enum"]=A{O{{"string",true},{"fret",integer(7)}}};
  refusal([&]{form.configure(object({{"contact",malformed}}),{},fence);});
}
